/// <summary>
/// PaffH 30.01.24
/// </summary>
/// <param name = "_batchHobId">RecId</param>
/// <returns>NDXBatchJobRicoKalkQuotationGet</returns>
static NDXBatchJobRicoKalkQuotationGet construct(RecId _batchHobId = 0)
{
    NDXBatchJobRicoKalkQuotationGet nDXBatchJobRicoKalkQuotationGet = new NDXBatchJobRicoKalkQuotationGet(_batchHobId);
    BatchHeader batchHeader = nDXBatchJobRicoKalkQuotationGet.parmBatchHeader();
    if (batchHeader.parmBatchGroup() != batchGroupId)
    {
        batchHeader.parmBatchGroup(nDXBatchJobRicoKalkQuotationGet.parmBatchGroup(batchGroupId, batchGroupIdDescription).Group);
    }
    return nDXBatchJobRicoKalkQuotationGet;
}

/// <summary>
/// PaffH 30.01.24
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>RefRecId</returns>
public RefRecId addTask(Args _args = NDXBatchJobRicoBVArgs::construct())
{
    NDXRicoKalkGetQuotationController controllerQuotation;
    if (_args is NDXBatchJobRicoBVArgs)
    {
        NDXBatchJobRicoBVArgs args = _args as NDXBatchJobRicoBVArgs;
        controllerQuotation = args.parmController();
        NDXRicoKalk2KBVBuildingProjectContract contractQuotation = controllerQuotation.getDataContractObject('_contract');
        if (!contractQuotation)
        {
            // Function %1 was called with an invalid value
            throw Error(strFmt("@SYS23264", classStr(NDXRicoKalk2KBVBuildingProjectContract)));
        }
        NDXRicoKalk2KBVBuildingProjectContract contractArgs = args.parmContract();
        batchHeader.parmRecurrenceData(args.parmRecurrenceData());
        batchHeader.parmCaption(args.parmCaption());
        controllerQuotation.parmDialogCaption(args.parmCaption());
        contractQuotation.parmCheckDays(contractArgs.parmCheckDays());
        contractQuotation.parmFromDate(contractArgs.parmFromDate());
        contractQuotation.parmToDate(contractArgs.parmToDate());
        contractQuotation.parmKBVBuildingProjectID(contractArgs.parmKBVBuildingProjectID());
        contractQuotation.parmKBVBuildingProjectIdFrom(contractArgs.parmKBVBuildingProjectIdFrom());
        contractQuotation.parmKBVBuildingProjectIdTo(contractArgs.parmKBVBuildingProjectIdTo());
        contractQuotation.parmFromDateOffset(contractArgs.parmFromDateOffset());
        contractQuotation.parmProtKopftyp(contractArgs.parmProtKopftyp());
        batchHeader.parmBatchJobActivePeriodId(args.parmBatchJobActivePeriodId());
    }
    batchHeader.parmStartDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));    // job shouldn't start immediately
    batchHeader.parmLogLevel(BatchLogLevel::Always);
    batchHeader.parmExecutingBy(#AdminUser);
    batchHeader.addTask(controllerQuotation);
    batchHeader.save();

    return batchHeader.parmBatchHeaderId();
}

/// <summary>
/// PaffH 30.01.24
/// </summary>
/// <returns>ClassDescription</returns>
client server static ClassDescription description()
{
    return "@NDXRicoBV:NDXRicoKalkGetQuotationController";
}
